/* From Uiverse.io by Na3ar-17  - Tags: simple, card, html, css */
.__UIV_SCOPE__ .card {
  padding: 0;
  margin: 0;
  box-sizing: border-box;
  font-family: Arial, Helvetica, sans-serif;
  width: 285px;
  padding: 8px;
  background-color: #282727;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  aspect-ratio: 16/12;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .card .no-image {
  border: 2px dashed #373737;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  aspect-ratio: 16/8;
}

.__UIV_SCOPE__ .card .no-image .icon {
  width: 60px;
  color: #373737;
}

.__UIV_SCOPE__ .card .image {
  width: 100%;
  aspect-ratio: 16/8;
}

.__UIV_SCOPE__ .card .image .picture {
  border-radius: 8px;
  width: inherit;
  aspect-ratio: 16/8;
}

.__UIV_SCOPE__ .card .content {
  display: flex;
  flex-direction: column;
  padding-top: 12px;
  padding-left: 4px;
}

.__UIV_SCOPE__ .card .content .name {
  font-size: 1.5rem;
  color: #ffffff;
}

.__UIV_SCOPE__ .card .content .time {
  padding-top: 12px;
  font-size: 0.875rem;
  color: #c5c5c5;
}

.__UIV_SCOPE__ .card:hover {
  -webkit-box-shadow: 0px 0px 15px -8px rgba(66, 68, 90, 1);
  -moz-box-shadow: 0px 0px 15px -8px rgba(66, 68, 90, 1);
  box-shadow: 0px 0px 15px -8px rgba(66, 68, 90, 1);
}
